{"content":"package expr

import (
	"fmt"
	"math"
	"strconv"
	"unicode/utf8"
)

// Token kinds.
const (
	tokEOF = iota
	tokNum
	tokIdent
	tokOp
	tokLParen
	tokRParen
	tokComma
	tokQuestion
	tokColon
)

type token struct {
	kind int
	text string
	pos  int // 0-based byte offset in the source
	num  float64
}

func isDigit(c byte) bool { return c >= '0' && c <= '9' }

func isIdentStart(c byte) bool {
	return c == '_' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
}

func isIdentChar(c byte) bool {
	return isIdentStart(c) || isDigit(c)
}

// lex converts src into a token stream. The stream always ends with a
// tokEOF token at position len(src). Lexical problems are reported as *Error.
func lex(src string) ([]token, error) {
	var toks []token
	i, n := 0, len(src)
	for i < n {
		c := src[i]
		switch {
		case c == ' ' || c == '\t' || c == '\n':
			i++
			continue
		}
		pos := i
		switch {
		case isDigit(c) || c == '.':
			j := i
			for j < n && isDigit(src[j]) {
				j++
			}
			if j < n && src[j] == '.' {
				j++
				for j < n && isDigit(src[j]) {
					j++
				}
			}
			// Optional exponent; the sign belongs to the literal.
			if j < n && (src[j] == 'e' || src[j] == 'E') {
				k := j + 1
				if k < n && (src[k] == '+' || src[k] == '-') {
					k++
				}
				if k < n && isDigit(src[k]) {
					for k < n && isDigit(src[k]) {
						k++
					}
					j = k
				}
			}
			v, err := strconv.ParseFloat(src[i:j], 64)
			if err != nil {
				return nil, &Error{Pos: pos, Msg: "invalid number"}
			}
			toks = append(toks, token{kind: tokNum, text: src[i:j], pos: pos, num: v})
			i = j
		case isIdentStart(c):
			j := i + 1
			for j < n && isIdentChar(src[j]) {
				j++
			}
			toks = append(toks, token{kind: tokIdent, text: src[i:j], pos: pos})
			i = j
		default:
			// Operators and punctuation.
			if i+1 < n {
				switch src[i:i+2] {
				case "<=", ">=", "==", "!=", "&&", "||":
					toks = append(toks, token{kind: tokOp, text: src[i : i+2], pos: pos})
					i += 2
					continue
				}
			}
			switch c {
			case '+', '-', '*', '/', '%', '^', '!':
				toks = append(toks, token{kind: tokOp, text: string(c), pos: pos})
			case '(':
				toks = append(toks, token{kind: tokLParen, text: "(", pos: pos})
			case ')':
				toks = append(toks, token{kind: tokRParen, text: ")", pos: pos})
			case ',':
				toks = append(toks, token{kind: tokComma, text: ",", pos: pos})
			case '?':
				toks = append(toks, token{kind: tokQuestion, text: "?", pos: pos})
			case ':':
				toks = append(toks, token{kind: tokColon, text: ":", pos: pos})
			default:
				r, _ := utf8.DecodeRuneInString(src[i:])
				toks = append(toks, token{kind: tokEOF, text: fmt.Sprintf("'%c'", r), pos: pos})
				return nil, &Error{Pos: pos, Msg: fmt.Sprintf("unexpected character '%c'", r)}
			}
			i++
		}
	}
	toks = append(toks, token{kind: tokEOF, pos: n})
	return toks, nil
}

