{"content":"package expr

import (
	"fmt"
	"math"
)

// node is a parsed expression tree node. Each node remembers the 0-based
// byte offset in the source at which it starts, for error reporting.
type node interface {
	eval(vars map[string]float64) (float64, error)
}

type numNode struct {
	pos int
	val float64
}

func (n *numNode) eval(map[string]float64) (float64, error) { return n.val, nil }

type varNode struct {
	pos  int
	name string
}

func (n *varNode) eval(vars map[string]float64) (float64, error) {
	v, ok := vars[n.name]
	if !ok {
		return 0, &Error{Pos: n.pos, Msg: fmt.Sprintf("unknown variable %q", n.name)}
	}
	return v, nil
}

type unaryNode struct {
	pos  int
	op   string
	arg  node
	name string // only for function calls
	args []node
}

func (n *unaryNode) eval(vars map[string]float64) (float64, error) {
	v, err := n.arg.eval(vars)
	if err != nil {
		return 0, err
	}
	switch n.op {
	case "-":
		return -v, nil
	case "+":
		return v, nil
	case "!":
		if v == 0 {
			return 1, nil
		}
		return 0, nil
	}
	panic("unknown unary op " + n.op)
}

type callNode struct {
	pos  int
	name string
	args []node
}

func (n *callNode) eval(vars map[string]float64) (float64, error) {
	vals := make([]float64, len(n.args))
	for i, a := range n.args {
		v, err := a.eval(vars)
		if err != nil {
			return 0, err
		}
		vals[i] = v
	}
	switch n.name {
	case "abs":
		return math.Abs(vals[0]), nil
	case "sqrt":
		if vals[0] < 0 {
			return 0, &Error{Pos: n.pos, Msg: "sqrt of negative number"}
		}
		return math.Sqrt(vals[0]), nil
	case "min":
		m := vals[0]
		for _, v := range vals[1:] {
			if v < m {
				m = v
			}
		}
		return m, nil
	case "max":
		m := vals[0]
		for _, v := range vals[1:] {
			if v > m {
				m = v
			}
		}
		return m, nil
	case "round":
		return math.Round(vals[0]), nil
	case "clamp":
		return math.Min(math.Max(vals[0], vals[1]), vals[2]), nil
	}
	panic("unknown function " + n.name)
}

type binNode struct {
	pos int
	op  string
	l   node
	r   node
}

func truthy(v float64) bool { return v != 0 }

func (n *binNode) eval(vars map[string]float64) (float64, error) {
	lv, err := n.l.eval(vars)
	if err != nil {
		return 0, err
	}
	switch n.op {
	case "&&":
		if !truthy(lv) {
			return 0, nil // short-circuit
		}
		rv, err := n.r.eval(vars)
		if err != nil {
			return 0, err
		}
		if truthy(rv) {
			return 1, nil
		}
		return 0, nil
	case "||":
		if truthy(lv) {
			return 1, nil // short-circuit
		}
		rv, err := n.r.eval(vars)
		if err != nil {
			return 0, err
		}
		if truthy(rv) {
			return 1, nil
		}
		return 0, nil
	}
	rv, err := n.r.eval(vars)
	if err != nil {
		return 0, err
	}
	switch n.op {
	case "+":
		return lv + rv, nil
	case "-":
		return lv - rv, nil
	case "*":
		return lv * rv, nil
	case "/":
		if rv == 0 {
			return 0, &Error{Pos: n.pos, Msg: "division by zero"}
		}
		return lv / rv, nil
	case "%":
		if rv == 0 {
			return 0, &Error{Pos: n.pos, Msg: "division by zero"}
		}
		return math.Mod(lv, rv), nil
	case "^":
		return math.Pow(lv, rv), nil
	case "==":
		if lv == rv {
			return 1, nil
		}
		return 0, nil
	case "!=":
		if lv != rv {
			return 1, nil
		}
		return 0, nil
	case "<":
		if lv < rv {
			return 1, nil
		}
		return 0, nil
	case "<=":
		if lv <= rv {
			return 1, nil
		}
		return 0, nil
	case ">":
		if lv > rv {
			return 1, nil
		}
		return 0, nil
	case ">=":
		if lv >= rv {
			return 1, nil
		}
		return 0, nil
	}
	panic("unknown binary op " + n.op)
}

type ternaryNode struct {
	pos  int
	cond node
	t    node
	f    node
}

func (n *ternaryNode) eval(vars map[string]float64) (float64, error) {
	c, err := n.cond.eval(vars)
	if err != nil {
		return 0, err
	}
	if truthy(c) {
		return n.t.eval(vars) // short-circuit
	}
	return n.f.eval(vars)
}
