{"content":"package expr

import "fmt"

// Built-in function table: name → exact arity, or -1 for variadic (min/max).
var builtins = map[string]int{
	"abs":   1,
	"sqrt":  1,
	"round": 1,
	"clamp": 3,
	"min":   -1,
	"max":   -1,
}

type parser struct {
	toks []token
	src  string
	pos  int
}

func (p *parser) peek() token { return p.toks[p.pos] }

func (p *parser) next() token {
	t := p.toks[p.pos]
	if p.pos < len(p.toks)-1 {
		p.pos++
	}
	return t
}

func (p *parser) isOp(op string) bool {
	t := p.peek()
	return t.kind == tokOp && t.text == op
}

// syntaxErr reports an unexpected token (or end of input).
func (p *parser) syntaxErr() *Error {
	t := p.peek()
	if t.kind == tokEOF {
		return &Error{Pos: len(p.src), Msg: "unexpected end of input"}
	}
	return &Error{Pos: t.pos, Msg: fmt.Sprintf("unexpected token %q", t.text)}
}

// expectToken consumes a specific token or returns an "expected" error at
// the position of the token found (or len(src) at end of input).
func (p *parser) expectToken(kind int, text string) error {
	t := p.peek()
	if t.kind == kind && (kind != tokOp || t.text == text) {
		p.next()
		return nil
	}
	if t.kind == tokEOF {
		return &Error{Pos: len(p.src), Msg: "expected " + text}
	}
	return &Error{Pos: t.pos, Msg: "expected " + text}
}

func parse(src string) (node, error) {
	toks, err := lex(src)
	if err != nil {
		return nil, err
	}
	p := &parser{toks: toks, src: src}
	root, err := p.parseTernary()
	if err != nil {
		return nil, err
	}
	if p.peek().kind != tokEOF {
		return nil, p.syntaxErr()
	}
	return root, nil
}

// parseTernary: c ? a : b, right-associative through the else branch.
func (p *parser) parseTernary() (node, error) {
	cond, err := p.parseOr()
	if err != nil {
		return nil, err
	}
	if p.peek().kind != tokQuestion {
		return cond, nil
	}
	p.next() // ?
	t, err := p.parseTernary()
	if err != nil {
		return nil, err
	}
	if err := p.expectToken(tokColon, `":"`); err != nil {
		return nil, err
	}
	f, err := p.parseTernary()
	if err != nil {
		return nil, err
	}
	return &ternaryNode{pos: p.posOf(cond), cond: cond, t: t, f: f}, nil
}

func (p *parser) parseOr() (node, error) {
	l, err := p.parseAnd()
	if err != nil {
		return nil, err
	}
	for p.isOp("||") {
		op := p.next()
		r, err := p.parseAnd()
		if err != nil {
			return nil, err
		}
		l = &binNode{pos: op.pos, op: "||", l: l, r: r}
	}
	return l, nil
}

func (p *parser) parseAnd() (node, error) {
	l, err := p.parseEquality()
	if err != nil {
		return nil, err
	}
	for p.isOp("&&") {
		op := p.next()
		r, err := p.parseEquality()
		if err != nil {
			return nil, err
		}
		l = &binNode{pos: op.pos, op: "&&", l: l, r: r}
	}
	return l, nil
}

func (p *parser) parseEquality() (node, error) {
	l, err := p.parseComparison()
	if err != nil {
		return nil, err
	}
	for p.isOp("==") || p.isOp("!=") {
		op := p.next()
		r, err := p.parseComparison()
		if err != nil {
			return nil, err
		}
		l = &binNode{pos: op.pos, op: op.text, l: l, r: r}
	}
	return l, nil
}

func (p *parser) parseComparison() (node, error) {
	l, err := p.parseAdditive()
	if err != nil {
		return nil, err
	}
	for p.isOp("<") || p.isOp("<=") || p.isOp(">") || p.isOp(">=") {
		op := p.next()
		r, err := p.parseAdditive()
		if err != nil {
			return nil, err
		}
		l = &binNode{pos: op.pos, op: op.text, l: l, r: r}
	}
	return l, nil
}

func (p *parser) parseAdditive() (node, error) {
	l, err := p.parseMultiplicative()
	if err != nil {
		return nil, err
	}
	for p.isOp("+") || p.isOp("-") {
		op := p.next()
		r, err := p.parseMultiplicative()
		if err != nil {
			return nil, err
		}
		l = &binNode{pos: op.pos, op: op.text, l: l, r: r}
	}
	return l, nil
}

func (p *parser) parseMultiplicative() (node, error) {
	l, err := p.parseUnary()
	if err != nil {
		return nil, err
	}
	for p.isOp("*") || p.isOp("/") || p.isOp("%") {
		op := p.next()
		r, err := p.parseUnary()
		if err != nil {
			return nil, err
		}
		l = &binNode{pos: op.pos, op: op.text, l: l, r: r}
	}
	return l, nil
}

// parseUnary handles prefix -, + and !; the operand is a power expression so
// that ^ binds tighter than unary on the left (-2^2 = -4).
func (p *parser) parseUnary() (node, error) {
	if p.isOp("-") || p.isOp("+") || p.isOp("!") {
		op := p.next()
		arg, err := p.parsePower()
		if err != nil {
			return nil, err
		}
		return &unaryNode{pos: op.pos, op: op.text, arg: arg}, nil
	}
	return p.parsePower()
}

// parsePower: base ^ unary — right-associative, and the right operand may
// itself be a unary expression (2^-1 = 0.5, 2^3^2 = 512).
func (p *parser) parsePower() (node, error) {
	base, err := p.parsePrimary()
	if err != nil {
		return nil, err
	}
	if !p.isOp("^") {
		return base, nil
	}
	op := p.next()
	exp, err := p.parseUnary()
	if err != nil {
		return nil, err
	}
	return &binNode{pos: op.pos, op: "^", l: base, r: exp}, nil
}

func (p *parser) parsePrimary() (node, error) {
	t := p.peek()
	switch t.kind {
	case tokNum:
		p.next()
		return &numNode{pos: t.pos, val: t.num}, nil
	case tokIdent:
		p.next()
		if name, ok := builtins[t.text]; ok && p.peek().kind == tokLParen {
			p.next() // (
			var args []node
			if p.peek().kind != tokRParen {
				for {
					a, err := p.parseTernary()
					if err != nil {
						return nil, err
					}
					args = append(args, a)
					if p.peek().kind == tokComma {
						p.next()
						continue
					}
					break
				}
			}
			if err := p.expectToken(tokRParen, `")"`); err != nil {
				return nil, err
			}
			return p.checkCall(t.text, t.pos, name, args)
		}
		return &varNode{pos: t.pos, name: t.text}, nil
	case tokLParen:
		p.next()
		e, err := p.parseTernary()
		if err != nil {
			return nil, err
		}
		if err := p.expectToken(tokRParen, `")"`); err != nil {
			return nil, err
		}
		return e, nil
	default:
		return nil, p.syntaxErr()
	}
}

// checkCall validates a built-in call at compile time.
func (p *parser) checkCall(name string, pos int, arity int, args []node) (node, error) {
	if arity < 0 { // min / max: at least 1
		if len(args) == 0 {
			return nil, &Error{Pos: pos, Msg: fmt.Sprintf("function %q expects at least 1 argument, got 0", name)}
		}
		return &callNode{pos: pos, name: name, args: args}, nil
	}
	if len(args) != arity {
		want := arity
		if want == 1 {
			want = 1
		}
		return nil, &Error{Pos: pos, Msg: fmt.Sprintf("function %q expects %d arguments, got %d", name, want, len(args))}
	}
	return &callNode{pos: pos, name: name, args: args}, nil
}

// posOf returns the source position of a node.
func (p *parser) posOf(n node) int {
	switch v := n.(type) {
	case *numNode:
		return v.pos
	case *varNode:
		return v.pos
	case *unaryNode:
		return v.pos
	case *binNode:
		return v.pos
	case *ternaryNode:
		return v.pos
	case *callNode:
		return v.pos
	}
	return 0
}
