{"content":"// Package expr implements a small expression language with float64
// arithmetic, comparisons, logic, a ternary operator and built-in
// math functions.
package expr

import (
	"fmt"
	"math"
	"sort"
)

// Error describes a lexical, syntax or runtime error. Pos is the 0-based
// byte offset in the source where the problem was detected.
type Error struct {
	Pos int
	Msg string
}

func (e *Error) Error() string { return fmt.Sprintf("%d: %s", e.Pos, e.Msg) }

// Program is a compiled expression, ready for repeated evaluation.
type Program struct {
	root node
}

// Compile parses src. It returns *Error on lexical or syntax errors.
func Compile(src string) (*Program, error) {
	root, err := parse(src)
	if err != nil {
		return nil, err
	}
	return &Program{root: root}, nil
}

// Eval evaluates the program with the given variable values. It returns
// *Error on runtime errors.
func (p *Program) Eval(vars map[string]float64) (float64, error) {
	v, err := p.root.eval(vars)
	if err != nil {
		return 0, err
	}
	if math.IsNaN(v) || math.IsInf(v, 0) {
		return 0, &Error{Pos: 0, Msg: "result is not finite"}
	}
	return v, nil
}

// Vars returns the sorted, de-duplicated names of the variables referenced
// by the program. Function names used in calls are not variables.
func (p *Program) Vars() []string {
	seen := make(map[string]bool)
	var walk func(n node)
	walk = func(n node) {
		switch v := n.(type) {
		case *numNode:
		case *varNode:
			seen[v.name] = true
		case *unaryNode:
			walk(v.arg)
		case *binNode:
			walk(v.l)
			walk(v.r)
		case *ternaryNode:
			walk(v.cond)
			walk(v.t)
			walk(v.f)
		case *callNode:
			for _, a := range v.args {
				walk(a)
			}
		}
	}
	walk(p.root)
	names := make([]string, 0, len(seen))
	for name := range seen {
		names = append(names, name)
	}
	sort.Strings(names)
	return names
}

// Eval compiles src and evaluates it with vars.
func Eval(src string, vars map[string]float64) (float64, error) {
	p, err := Compile(src)
	if err != nil {
		return 0, err
	}
	return p.Eval(vars)
}
