func floatEq(a, b float64) bool { return math.Abs(a-b) < 1e-9 || a == b }

// TestEval covers value semantics: arithmetic, precedence, booleans,
// functions and short-circuiting.
func TestEval(t *testing.T) {
	cases := []struct {
		src  string
		vars map[string]float64
		want float64
	}{
		{"1 + 2 * 3", nil, 7},
		{"(1 + 2) * 3", nil, 9},
		{"10 - 2 - 3", nil, 5},
		{"100 / 10 / 2", nil, 5},
		{"7 % 3", nil, 1},
		{"-7 % 3", nil, -1}, // math.Mod, sign of dividend
		{"2.5E-2", nil, 0.025},
		{".5", nil, 0.5},
		{"1.", nil, 1},
		{"1e3", nil, 1000},
		{"123", nil, 123},
		{"true", nil, 1},
		{"false", nil, 0},
		{"!0", nil, 1},
		{"!1", nil, 0},
		{"!!2", nil, 1},
		{"2 - -3", nil, 5},
		{"-(1+2)", nil, -3},
		// power: right-associative, binds tighter than unary on the left
		{"2^3^2", nil, 512},
		{"2^2^2", nil, 16},
		{"-2^2", nil, -4},
		{"2^-1", nil, 0.5},
		{"2^+2", nil, 4},
		{"2^2 * 2", nil, 8},
		{"2 * 3^2", nil, 18},
		// comparisons and equality return 1/0
		{"1 < 2", nil, 1},
		{"2 < 2", nil, 0},
		{"2 <= 2", nil, 1},
		{"3 > 3", nil, 0},
		{"3 >= 3", nil, 1},
		{"1 == 1", nil, 1},
		{"1 != 2", nil, 1},
		{"1 == 2", nil, 0},
		// logical ops return 1/0
		{"1 && 2", nil, 1},
		{"1 && 0", nil, 0},
		{"0 || 3", nil, 1},
		{"0 || 0", nil, 0},
		{"1 || 0", nil, 1},
		{"1 < 2 && 2 < 3", nil, 1},
		// short-circuiting: unneeded operand must not be evaluated
		{"1 && 1/0", nil, 1},
		{"0 || 1/0", nil, 0},
		{"0 ? 1/0 : 2", nil, 2},
		{"1 ? 1 : 1/0", nil, 1},
		{"1 ? 1/0 : 1", nil, 1},
		{"0 ? 1 : 1/0", nil, 0},
		// ternary, right-associative: a ? b : c ? d : e = a ? b : (c ? d : e)
		{"a ? b : c ? d : e", map[string]float64{"a": 0, "b": 5, "c": 1, "d": 7, "e": 9}, 7},
		{"a ? b : c ? d : e", map[string]float64{"a": 1, "b": 5, "c": 1, "d": 7, "e": 9}, 5},
		{"a ? b : c ? d : e", map[string]float64{"a": 0, "b": 5, "c": 0, "d": 7, "e": 9}, 9},
		{"0.5 ? 1 : 2", nil, 1}, // any non-zero is truthy
		// variables
		{"x + y * x", map[string]float64{"x": 2, "y": 3}, 8},
		// built-ins
		{"abs(-3)", nil, 3},
		{"abs(3)", nil, 3},
		{"sqrt(4)", nil, 2},
		{"abs(sqrt(16))", nil, 4},
		{"min(3, 1, 2)", nil, 1},
		{"max(1, 2, 3)", nil, 3},
		{"max(min(3, 2), 1)", nil, 2},
		{"round(2.5)", nil, 3},
		{"round(-2.5)", nil, -3},
		{"round(2.4)", nil, 2},
		{"clamp(5, 0, 3)", nil, 3},
		{"clamp(-1, 0, 3)", nil, 0},
		{"clamp(1, 0, 3)", nil, 1},
		// a built-in name without a call is a variable reference
		{"abs", map[string]float64{"abs": 7}, 7},
	}
	for _, tc := range cases {
		got, err := expr.Eval(tc.src, tc.vars)
		if err != nil {
			t.Fatalf("Eval(%q, %v): %v", tc.src, tc.vars, err)
		}
		if !floatEq(got, tc.want) {
			t.Errorf("Eval(%q, %v) = %v, want %v", tc.src, tc.vars, got, tc.want)
		}
	}
}

func wantErr(pos int, msg string) *expr.Error {
	return &expr.Error{Pos: pos, Msg: msg}
}

func assertErr(t *testing.T, got error, want *expr.Error) {
	t.Helper()
	e, ok := got.(*expr.Error)
	if !ok {
		t.Fatalf("expected *expr.Error, got %T (%v)", got, got)
	}
	if *e != *want {
		t.Fatalf("got %v (Pos=%d Msg=%q), want %v", e, e.Pos, e.Msg, want)
	}
}

// TestCompileErrors covers lexical and syntax error messages and positions.
func TestCompileErrors(t *testing.T) {
	cases := []struct {
		src  string
		want *expr.Error
	}{
		{"", wantErr(0, "unexpected end of input")},
		{"   ", wantErr(3, "unexpected end of input")},
		{"1 + @", wantErr(4, "unexpected character '@'")},
		{"$1", wantErr(0, "unexpected character '$'")},
		{"1 2", wantErr(2, `unexpected token "2"`)},
		{"1 +", wantErr(3, "unexpected end of input")},
		{"1 + * 2", wantErr(4, `unexpected token "*"`)},
		{"(1+2", wantErr(4, `expected ")"`)},
		{"(1 2)", wantErr(2, `expected ")"`)},
		{"1 ? 2", wantErr(5, `expected ":"`)},
		{"1 ? 2 : ", wantErr(8, "unexpected end of input")},
		{"1 ? : 2", wantErr(4, `expected ":"`)},
		{"1 2 3", wantErr(2, `unexpected token "2"`)},
		{"()", wantErr(1, `unexpected token ")"`)},
		{")", wantErr(0, `unexpected token ")"`)},
		{"(1+2) 3", wantErr(6, `unexpected token "3"`)},
		{"2 ** 3", wantErr(3, `unexpected token "*"`)},
		{"1 ==", wantErr(4, "unexpected end of input")},
		{"abs(1", wantErr(5, `expected ")"`)},
		{"abs(1,, 2)", wantErr(6, `unexpected token ")"`)},
		{"foo(1)", wantErr(0, `unknown function "foo"`)},
		{"abs(1, 2)", wantErr(0, `function "abs" expects 1 arguments, got 2`)},
		{"abs()", wantErr(0, `function "abs" expects 1 arguments, got 0`)},
		{"sqrt(1, 2, 3)", wantErr(0, `function "sqrt" expects 1 arguments, got 3`)},
		{"round()", wantErr(0, `function "round" expects 1 arguments, got 0`)},
		{"clamp(1)", wantErr(0, `function "clamp" expects 3 arguments, got 1`)},
		{"clamp(1, 2, 3, 4)", wantErr(0, `function "clamp" expects 3 arguments, got 4`)},
		{"min()", wantErr(0, `function "min" expects at least 1 argument, got 0`)},
		{"max()", wantErr(0, `function "max" expects at least 1 argument, got 0`)},
	}
	for _, tc := range cases {
		_, err := expr.Compile(tc.src)
		if err == nil {
			t.Fatalf("Compile(%q): expected error, got none", tc.src)
		}
		assertErr(t, err, tc.want)
	}
}

// TestRuntimeErrors covers runtime error messages and positions.
func TestRuntimeErrors(t *testing.T) {
	cases := []struct {
		src  string
		vars map[string]float64
		want *expr.Error
	}{
		{"1 / 0", nil, wantErr(2, "division by zero")},
		{"5 % 0", nil, wantErr(2, "division by zero")},
		{"1 / (x - 1)", map[string]float64{"x": 1}, wantErr(4, "division by zero")},
		{"1 / 2 % 0", nil, wantErr(5, "division by zero")},
		{"x + 1", nil, wantErr(0, `unknown variable "x"`)},
		{"1 + y", nil, wantErr(3, `unknown variable "y"`)},
		{"1 * x * 2", map[string]float64{"x": 0}, wantErr(4, `unknown variable "x"`)},
		{"sqrt(-1)", nil, wantErr(0, "sqrt of negative number")},
		{"sqrt(1 - 3)", nil, wantErr(0, "sqrt of negative number")},
		{"sqrt(0)", nil, wantErr(0, "sqrt of negative number")}, // guard: 0 is fine; this line checks only via table below
		{"1e999", nil, wantErr(0, "result is not finite")},
		{"x", map[string]float64{"x": math.Inf(1)}, wantErr(0, "result is not finite")},
		{"x", map[string]float64{"x": math.Inf(-1)}, wantErr(0, "result is not finite")},
		{"x", map[string]float64{"x": math.NaN()}, wantErr(0, "result is not finite")},
	}
	// sqrt(0) is NOT an error; remove it from the error table.
	for _, tc := range cases {
		if tc.src == "sqrt(0)" {
			continue
		}
		_, err := expr.Eval(tc.src, tc.vars)
		if err == nil {
			t.Fatalf("Eval(%q): expected error, got none", tc.src)
		}
		assertErr(t, err, tc.want)
	}
	if v, err := expr.Eval("sqrt(0)", nil); err != nil || v != 0 {
		t.Fatalf("Eval(sqrt(0)) = %v, %v; want 0, nil", v, err)
	}
}

// TestErrorString checks the Error format.
func TestErrorString(t *testing.T) {
	e := &expr.Error{Pos: 3, Msg: "division by zero"}
	if e.Error() != "3: division by zero" {
		t.Fatalf("Error() = %q", e.Error())
	}
}

// TestVars checks Vars() reporting of referenced variables.
func TestVars(t *testing.T) {
	cases := []struct {
		src  string
		want []string
	}{
		{"1 + 2", []string{}},
		{"x + y * x", []string{"x", "y"}},
		{"x * x", []string{"x"}},
		{"z", []string{"z"}},
		{"abs(x)", []string{"x"}},
		{"abs(x) + max(y, z)", []string{"x", "y", "z"}},
		{"abs", []string{"abs"}}, // name without call is a variable
		{"x ? a : b", []string{"a", "b", "x"}},
		{"1 && x || y", []string{"x", "y"}},
	}
	for _, tc := range cases {
		p, err := expr.Compile(tc.src)
		if err != nil {
			t.Fatalf("Compile(%q): %v", tc.src, err)
		}
		if got := p.Vars(); !reflect.DeepEqual(got, tc.want) {
			t.Errorf("Vars() for %q = %v, want %v", tc.src, got, tc.want)
		}
	}
}

// TestProgramReuse checks that a Program can be evaluated repeatedly with
// different variables.
func TestProgramReuse(t *testing.T) {
	p, err := expr.Compile("x * 2 + 1")
	if err != nil {
		t.Fatal(err)
	}
	if v, err := p.Eval(map[string]float64{"x": 1}); err != nil || v != 3 {
		t.Fatalf("Eval x=1: %v %v", v, err)
	}
	if v, err := p.Eval(map[string]float64{"x": 10}); err != nil || v != 21 {
		t.Fatalf("Eval x=10: %v %v", v, err)
	}
	if _, err := p.Eval(nil); err == nil {
		t.Fatal("expected unknown variable error with nil vars")
	}
}

// TestTernaryPrecedence checks mixing of ternary with logical operators and
// nested ternaries.
func TestTernaryPrecedence(t *testing.T) {
	// (a || b) ? 1 : 0
	v, err := expr.Eval("a || b ? 1 : 0", map[string]float64{"a": 0, "b": 2})
	if err != nil || v != 1 {
		t.Fatalf("a||b ? 1:0 = %v %v", v, err)
	}
	// nested left: a ? (b ? c : d) : e
	v, err = expr.Eval("a ? b ? c : d : e", map[string]float64{"a": 1, "b": 0, "c": 3, "d": 4, "e": 5})
	if err != nil || v != 4 {
		t.Fatalf("nested ternary = %v %v, want 4", v, err)
	}
}

// TestShortCircuitNoSideEffect checks that the unneeded branch is not
// evaluated, including for unknown variables in it.
func TestShortCircuitNoSideEffect(t *testing.T) {
	if _, err := expr.Eval("1 && unknownVar", nil); err != nil {
		t.Fatalf("1 && unknownVar should short-circuit, got %v", err)
	}
	if _, err := expr.Eval("0 || unknownVar", nil); err != nil {
		t.Fatalf("0 || unknownVar should short-circuit, got %v", err)
	}
	if _, err := expr.Eval("1 ? 1 : unknownVar", nil); err != nil {
		t.Fatalf("1 ? 1 : unknownVar should short-circuit, got %v", err)
	}
	if _, err := expr.Eval("0 ? unknownVar : 2", nil); err != nil {
		t.Fatalf("0 ? unknownVar : 2 should short-circuit, got %v", err)
	}
}

// TestWhitespaceAndIdentifiers exercises whitespace handling and identifiers.
func TestWhitespaceAndIdentifiers(t *testing.T) {
	if v, err := expr.Eval("x\n\t+ y", map[string]float64{"x": 1, "y": 2}); err != nil || v != 3 {
		t.Fatalf("whitespace: %v %v", v, err)
	}
	if v, err := expr.Eval("_a1 + B", map[string]float64{"_a1": 1, "B": 2}); err != nil || v != 3 {
		t.Fatalf("identifiers: %v %v", v, err)
	}
	// true/false are keywords, not variables
	if v, err := expr.Eval("true + false", map[string]float64{"true": 100, "false": 100}); err != nil || v != 1 {
		t.Fatalf("true+false: %v %v", v, err)
	}
}

// TestUnaryPowerInterplay covers the precedence rules around unary and ^.
func TestUnaryPowerInterplay(t *testing.T) {
	cases := []struct {
		src  string
		vars map[string]float64
		want float64
	}{
		{"-2^2", nil, -4},
		{"-(-2)^2", nil, -4},
		{"2^2", nil, 4},
		{"1 - 2^2", nil, -3},
		{"2^-2", nil, 0.25},
		{"!2^2", nil, 0},
		{"!0^1", nil, 1},
		{"2^3^2", nil, 512},
	}
	for _, tc := range cases {
		got, err := expr.Eval(tc.src, tc.vars)
		if err != nil {
			t.Fatalf("Eval(%q): %v", tc.src, err)
		}
		if !floatEq(got, tc.want) {
			t.Errorf("Eval(%q) = %v, want %v", tc.src, got, tc.want)
		}
	}
}
